WITH parsed AS (SELECT id, plan, effective_from, SLICE(tier_limits, 1, 2) AS first_two_limits, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE effective_from <= '2024-01-07') SELECT id, entry_price, SUM(entry_price) OVER w_grp AS running_sum_entry_price, AVG(entry_price) OVER w_grp AS running_avg_entry_price, MIN(entry_price) OVER w_grp AS running_min_entry_price, MAX(entry_price) OVER w_grp AS running_max_entry_price, LAG(avg_tier_price, 1) OVER (PARTITION BY plan ORDER BY entry_price ASC, id ASC) AS prev_avg_tier_price FROM parsed WINDOW w_grp AS (PARTITION BY plan ORDER BY effective_from ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
